(function(){"use strict";const d=[".animate-fade-up",".animate-fade-in",".animate-slide-in"],f={"delay-100":"100ms","delay-200":"200ms","delay-300":"300ms","delay-400":"400ms","delay-500":"500ms"};function a(){const n=document.querySelectorAll(d.join(", "));if(!n.length)return;n.forEach(t=>{t.classList.contains("animate-fade-up")?(t.style.opacity="0",t.style.transform="translateY(28px)"):t.classList.contains("animate-fade-in")?t.style.opacity="0":t.classList.contains("animate-slide-in")&&(t.style.opacity="0",t.style.transform="translateX(20px)");let e="0ms";for(const[s,o]of Object.entries(f))if(t.classList.contains(s)){e=o;break}t.style.transition=`opacity 0.65s cubic-bezier(0.16, 1, 0.3, 1) ${e}, transform 0.65s cubic-bezier(0.16, 1, 0.3, 1) ${e}`});const r=new IntersectionObserver(t=>{t.forEach(e=>{if(e.isIntersecting){const s=e.target;s.style.opacity="1",s.style.transform="translateY(0) translateX(0)",r.unobserve(s)}})},{threshold:.08,rootMargin:"0px 0px -40px 0px"});n.forEach(t=>r.observe(t))}function c(){const n=document.querySelectorAll(".counter-value");if(!n.length)return;const r=new IntersectionObserver(t=>{t.forEach(e=>{if(e.isIntersecting){const s=e.target,o=parseInt(s.dataset.target||"0",10);if(!o)return;let i=0;const u=o/(2e3/16),m=setInterval(()=>{i+=u,i>=o&&(i=o,clearInterval(m)),s.textContent=Math.floor(i).toLocaleString("en")},16);r.unobserve(s)}})},{threshold:.3});n.forEach(t=>r.observe(t))}function l(){const n=document.getElementById("reading-progress");n&&window.addEventListener("scroll",()=>{const r=window.scrollY,t=document.documentElement.scrollHeight-window.innerHeight,e=t>0?r/t*100:0;n.style.width=Math.min(e,100)+"%"},{passive:!0})}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",()=>{a(),c(),l()}):(a(),c(),l())})();
